from __future__ import annotations

import json
import re
from dataclasses import asdict

from .model import DecisionTable
from .validate import has_errors, validate_table


class JavaScriptGenerationError(ValueError):
    """Raised when a table cannot be represented by the generated JavaScript runtime."""


_PYTHON_ONLY_REGEX_MARKERS = (
    "(?P<",
    "(?P=",
    "\\A",
    "\\Z",
    "\\N{",
    "(?#",
    "(?(",
    "(?>",
)
_INLINE_FLAG_RE = re.compile(r"\(\?[aiLmsux-]+[:)]")
_UNICODE_SHORTHAND_RE = re.compile(r"(?<!\\)\\[wWdDsS]")


def generate_javascript(table: DecisionTable) -> str:
    """Generate one dependency-free ESM module for a canonical decision table."""
    diagnostics = validate_table(table)
    if has_errors(diagnostics):
        details = "; ".join(
            f"{item.code} {item.path}: {item.message}"
            for item in diagnostics
            if item.severity == "error"
        )
        raise JavaScriptGenerationError(f"Cannot generate runtime for an invalid table: {details}")

    _check_portability(table)
    payload = json.dumps(
        asdict(table),
        sort_keys=True,
        ensure_ascii=False,
        default=str,
        separators=(",", ":"),
    )

    return f'''// Generated by Decision Tables as Code. Do not edit by hand.\n// Table: {table.id}\n\nconst TABLE = {payload};\n\nconst HAS_OWN = (object, key) => Object.prototype.hasOwnProperty.call(object, key);\n\nfunction isoDate(value) {{\n  if (value instanceof Date) {{\n    if (Number.isNaN(value.getTime())) throw new TypeError("Invalid Date supplied as asOf");\n    return value.toISOString().slice(0, 10);\n  }}\n  if (typeof value !== "string" || !/^\\d{{4}}-\\d{{2}}-\\d{{2}}$/.test(value)) {{\n    throw new TypeError("asOf must be a YYYY-MM-DD string or Date");\n  }}\n  const parsed = new Date(value + "T00:00:00Z");\n  if (Number.isNaN(parsed.getTime()) || parsed.toISOString().slice(0, 10) !== value) {{\n    throw new TypeError(`Invalid ISO date ${{JSON.stringify(value)}}; expected YYYY-MM-DD`);\n  }}\n  return value;\n}}\n\nfunction operatorMatches(operator, expected, value, present) {{\n  if (operator === "exists") return present === Boolean(expected);\n  if (!present) return false;\n  if (operator === "eq") return value === expected;\n  if (operator === "ne") return value !== expected;\n  if (operator === "in") return expected.includes(value);\n  if (operator === "not_in") return !expected.includes(value);\n  if (operator === "gt") return value > expected;\n  if (operator === "gte") return value >= expected;\n  if (operator === "lt") return value < expected;\n  if (operator === "lte") return value <= expected;\n  if (operator === "between") {{\n    if (!Array.isArray(expected) || expected.length !== 2) throw new Error("between requires [minimum, maximum]");\n    return expected[0] <= value && value <= expected[1];\n  }}\n  if (operator === "regex") {{\n    const text = String(value);\n    const match = new RegExp(String(expected), "u").exec(text);\n    return match !== null && match.index === 0 && match[0].length === text.length;\n  }}\n  throw new Error(`Unsupported condition operator: ${{operator}}`);\n}}\n\nfunction conditionMatches(condition, value, present) {{\n  if (condition === "*") return present;\n  if (condition !== null && typeof condition === "object" && !Array.isArray(condition)) {{\n    return Object.entries(condition).every(([operator, expected]) => operatorMatches(operator, expected, value, present));\n  }}\n  if (Array.isArray(condition)) return condition.includes(value);\n  return value === condition;\n}}\n\nfunction ruleMatches(rule, facts) {{\n  return Object.entries(rule.when).every(([name, condition]) => {{\n    const present = HAS_OWN(facts, name);\n    return conditionMatches(condition, facts[name], present);\n  }});\n}}\n\nfunction ruleIsEffective(rule, asOf) {{\n  if (rule.effective_from == null && rule.effective_to == null) return true;\n  if (asOf == null) {{\n    throw new Error(`Rule ${{JSON.stringify(rule.id)}} has effective dates; pass an explicit asOf date for deterministic evaluation`);\n  }}\n  const day = isoDate(asOf);\n  if (rule.effective_from != null && day < rule.effective_from) return false;\n  if (rule.effective_to != null && day > rule.effective_to) return false;\n  return true;\n}}\n\nfunction orderedRules() {{\n  return TABLE.rules\n    .map((rule, index) => ({{ rule, index }}))\n    .sort((left, right) => {{\n      const lp = left.rule.priority;\n      const rp = right.rule.priority;\n      if (lp == null && rp != null) return 1;\n      if (lp != null && rp == null) return -1;\n      if (lp != null && rp != null && lp !== rp) return lp - rp;\n      return left.index - right.index;\n    }})\n    .map(item => item.rule);\n}}\n\nexport function matchingRules(facts, options = {{}}) {{\n  if (facts === null || typeof facts !== "object" || Array.isArray(facts)) throw new TypeError("facts must be an object");\n  return orderedRules().filter(rule => ruleIsEffective(rule, options.asOf) && ruleMatches(rule, facts));\n}}\n\nexport function evaluate(facts, options = {{}}) {{\n  const matches = matchingRules(facts, options);\n  let selected;\n  let outputs;\n\n  if (TABLE.hit_policy === "first") {{\n    selected = matches.slice(0, 1);\n    outputs = selected.length ? {{ ...selected[0].then }} : null;\n  }} else if (TABLE.hit_policy === "unique") {{\n    if (matches.length > 1) {{\n      throw new Error(`UNIQUE hit policy violated; matched rules: ${{matches.map(rule => rule.id).join(", ")}}`);\n    }}\n    selected = matches;\n    outputs = selected.length ? {{ ...selected[0].then }} : null;\n  }} else if (TABLE.hit_policy === "collect") {{\n    selected = matches;\n    outputs = selected.map(rule => ({{ ...rule.then }}));\n  }} else {{\n    throw new Error(`Unsupported hit policy: ${{TABLE.hit_policy}}`);\n  }}\n\n  return {{\n    table_id: TABLE.id,\n    matched_rule_ids: selected.map(rule => rule.id),\n    outputs,\n  }};\n}}\n\nexport const tableId = TABLE.id;\nexport const hitPolicy = TABLE.hit_policy;\n'''


def generate_typescript_declaration(table: DecisionTable) -> str:
    """Generate a small declaration file for the generated ESM runtime."""
    if table.hit_policy == "collect":
        output_shape = "Record<string, unknown>[]"
    else:
        output_shape = "Record<string, unknown> | null"
    return f'''// Generated by Decision Tables as Code.\nexport type Facts = Record<string, unknown>;\nexport interface EvaluateOptions {{ asOf?: string | Date; }}\nexport interface DecisionResult {{\n  table_id: {json.dumps(table.id)};\n  matched_rule_ids: string[];\n  outputs: {output_shape};\n}}\nexport interface RuleMatch {{\n  id: string;\n  when: Record<string, unknown>;\n  then: Record<string, unknown>;\n  [key: string]: unknown;\n}}\nexport function matchingRules(facts: Facts, options?: EvaluateOptions): RuleMatch[];\nexport function evaluate(facts: Facts, options?: EvaluateOptions): DecisionResult;\nexport const tableId: {json.dumps(table.id)};\nexport const hitPolicy: {json.dumps(table.hit_policy)};\n'''


def _check_portability(table: DecisionTable) -> None:
    for rule in table.rules:
        for field_name, condition in rule.when.items():
            if not isinstance(condition, dict) or "regex" not in condition:
                continue
            pattern = str(condition["regex"])
            if (
                any(marker in pattern for marker in _PYTHON_ONLY_REGEX_MARKERS)
                or _INLINE_FLAG_RE.search(pattern)
                or _UNICODE_SHORTHAND_RE.search(pattern)
            ):
                raise JavaScriptGenerationError(
                    f"Rule {rule.id!r} input {field_name!r} uses a Python-specific or Unicode-sensitive regex construct that cannot be emitted with JavaScript parity"
                )
            try:
                re.compile(pattern)
            except re.error as exc:
                raise JavaScriptGenerationError(
                    f"Rule {rule.id!r} has invalid regex {pattern!r}: {exc}"
                ) from exc
